import{_ as i,o as a,c as n,a2 as o}from"./chunks/framework.CDpkVv68.js";const u=JSON.parse('{"title":"Cooking","description":"","frontmatter":{},"headers":[],"relativePath":"en/game-design/professions/cooking.md","filePath":"en/game-design/professions/cooking.md"}'),s={name:"en/game-design/professions/cooking.md"};function t(r,e,l,c,d,p){return a(),n("div",null,[...e[0]||(e[0]=[o('<h1 id="cooking" tabindex="-1">Cooking <a class="header-anchor" href="#cooking" aria-label="Permalink to &quot;Cooking&quot;">​</a></h1><p><strong>Design status:</strong> Proposed; all mechanics, examples and technique paths below remain candidates. <strong>Implementation:</strong> no implementation of this redesign is established by this documentation batch. <strong>Availability:</strong> not established. <strong>Verification:</strong> documentation review only; no gameplay test. <strong>Reviewed:</strong> 2026-10-09 for public projection; design status and mechanics preserved from the canonical specification.</p><p><a href="/Syrolands-Public/en/guide/professions/cooking.html">Player-facing overview</a> · <a href="/Syrolands-Public/en/game-design/professions/profession-system.html">Profession System</a></p><h2 id="purpose-and-profession-loop" tabindex="-1">Purpose and profession loop <a class="header-anchor" href="#purpose-and-profession-loop" aria-label="Permalink to &quot;Purpose and profession loop&quot;">​</a></h2><p>Cooking should be a physical world activity, not a recipe-list menu.</p><h3 id="stations" tabindex="-1">Stations <a class="header-anchor" href="#stations" aria-label="Permalink to &quot;Stations&quot;">​</a></h3><ul><li>wilderness cooking stand built around a campfire (via Camping);</li><li>kitchen/stove/oven/grill in houses, inns, taverns;</li><li>possible richer camp setups at higher Camping.</li></ul><h3 id="station-interface" tabindex="-1">Station interface <a class="header-anchor" href="#station-interface" aria-label="Permalink to &quot;Station interface&quot;">​</a></h3><ul><li>represents the station;</li><li>drag/drop ingredients from backpack;</li><li>areas such as pot, grill, preparation table;</li><li>ingredient starts cooking immediately when placed.</li></ul><p>Ingredients have cooking states/windows, e.g.:</p><ul><li>raw;</li><li>rare;</li><li>medium;</li><li>well done;</li><li>burnt;</li></ul><p>or equivalent ingredient-specific states.</p><p>Different ingredients have different timing/state progressions.</p><p>Skill should widen tolerances and improve control rather than automate all skill.</p><p>Possible thermal abstraction:</p><ul><li>Low</li><li>Medium</li><li>High</li><li>Very High</li></ul><p>Fuel/fire quality can connect with Camping/Lumberjacking without requiring excessive simulation.</p><h3 id="recipes" tabindex="-1">Recipes <a class="header-anchor" href="#recipes" aria-label="Permalink to &quot;Recipes&quot;">​</a></h3><ul><li>can require multiple ingredients at specific preparation states;</li><li>final assembly happens at a preparation/assembly area;</li><li>recipes can be discovered via exploration, books, cooks, cultures, quests, ruins, experimentation.</li></ul><p>Recipe quality may depend on:</p><ul><li>ingredient quality;</li><li>cooking state/timing;</li><li>skill;</li><li>station;</li><li>execution.</li></ul><p>Food should not merely become potion-like stat buffs. Prefer effects around:</p><ul><li>satiation;</li><li>nutrition;</li><li>recovery;</li><li>stamina efficiency;</li><li>fatigue;</li><li>temperature resistance;</li><li>concentration/recovery;</li><li>situational survival benefits.</li></ul><h3 id="taste-codex-personal-taste" tabindex="-1">Taste Codex / personal taste <a class="header-anchor" href="#taste-codex-personal-taste" aria-label="Permalink to &quot;Taste Codex / personal taste&quot;">​</a></h3><ul><li>each character can discover personal food preferences through eating;</li><li>preferences should not be shown fully at character creation;</li><li>discovering a favorite dish/family can produce especially high satisfaction/comfort effects;</li><li>this gives players an incentive to try new foods;</li><li>chefs benefit from broad culinary knowledge and completion of their culinary journal.</li></ul><p>This can become a profession endgame.</p><h2 id="knowledge-and-specialization" tabindex="-1">Knowledge and specialization <a class="header-anchor" href="#knowledge-and-specialization" aria-label="Permalink to &quot;Knowledge and specialization&quot;">​</a></h2><p><strong>Culinary Journal / Taste Codex.</strong> Cooking styles, recipes and regional food knowledge; a broad journal and mastery of preparation can sustain a culinary endgame.</p><h2 id="shared-progression-production-and-economy" tabindex="-1">Shared progression, production and economy <a class="header-anchor" href="#shared-progression-production-and-economy" aria-label="Permalink to &quot;Shared progression, production and economy&quot;">​</a></h2><p>The <a href="/Syrolands-Public/en/game-design/characters/skills-and-skillcap.html">character skill framework</a> owns teaching and cap/gain direction. The <a href="/Syrolands-Public/en/game-design/professions/profession-system.html">Profession System</a> owns craft discovery, knowledge sharing, manual mastery, batch production, commissions and multidimensional reputation. Those rules are not independently redefined here. The <a href="/Syrolands-Public/en/game-design/items/itemization-and-craft-quality.html">quality specification</a> owns the shared result envelope and rare item properties.</p><h2 id="related-skills-and-field-interactions" tabindex="-1">Related skills and field interactions <a class="header-anchor" href="#related-skills-and-field-interactions" aria-label="Permalink to &quot;Related skills and field interactions&quot;">​</a></h2><p>Camping supplies field fire/stations; Lumberjacking informs fuel; food recovery may intersect Healing and the proposed Meditation/Concentration system. Exact effects and stacking are unresolved.</p><p><a href="/Syrolands-Public/en/game-design/professions/alchemy.html">Alchemy</a> · <a href="/Syrolands-Public/en/game-design/professions/lumberjacking.html">Lumberjacking</a> · <a href="/Syrolands-Public/en/game-design/living-world.html#knowledge-professions-and-traces">Camping and world knowledge</a> · <a href="/Syrolands-Public/en/game-design/magic.html#meditation-and-concentration">Meditation and Concentration</a>.</p><h2 id="abstraction-and-technical-boundary" tabindex="-1">Abstraction and technical boundary <a class="header-anchor" href="#abstraction-and-technical-boundary" aria-label="Permalink to &quot;Abstraction and technical boundary&quot;">​</a></h2><p>Keep only state and feedback that support meaningful decisions. The <a href="/Syrolands-Public/en/game-design/professions/profession-system.html#performance-abstraction-and-authority">shared abstraction/authority constraints</a> and living-world architecture apply; persistence requires a separate technical design. Nothing here selects packet IDs, schemas, timers, UI assets or runtime algorithms.</p><h2 id="open-questions" tabindex="-1">Open questions <a class="header-anchor" href="#open-questions" aria-label="Permalink to &quot;Open questions&quot;">​</a></h2><p>Cooking windows and feedback precision; station access and ingredient ownership; recipe/assembly failure; fuel/heat abstraction; taste discovery, persistence and satisfaction limits; recovery versus medicine and potion stacking. No nutrition formula or free combat buff is established.</p><p>The <a href="/Syrolands-Public/en/game-design/professions/profession-system.html#open-questions-and-reconciliation-required">shared reconciliation register</a> owns cross-system conflicts. Existing combat experiments and evidence do not validate this profession redesign.</p>',38)])])}const m=i(s,[["render",t]]);export{u as __pageData,m as default};
